import crypto from "node:crypto";import { prisma } from "@/lib/prisma";import { mobileApiError,mobileJson,mobileOptions,requireMobileUser } from "@/lib/mobile-api";import { requestOrigin } from "@/lib/user-perks";import { serializeVideoLive } from "@/lib/video-live";import { emitToUser } from "@/lib/realtime";
export function OPTIONS(){return mobileOptions()}
export async function GET(request){try{await requireMobileUser(request);const rows=await prisma.videoLiveSession.findMany({where:{status:"LIVE"},include:{host:true},orderBy:{startedAt:"desc"},take:100});return mobileJson({success:true,data:{sessions:await Promise.all(rows.map(r=>serializeVideoLive(r,requestOrigin(request))))}})}catch(e){return mobileApiError(e,"LIVE_FEED_FAILED")}}
export async function POST(request){try{const user=await requireMobileUser(request),body=await request.json(),title=String(body?.title??"").trim();if(!title||title.length>120)throw Object.assign(new Error("A title between 1 and 120 characters is required."),{code:"VALIDATION_ERROR"});const existing=await prisma.videoLiveSession.findFirst({where:{hostId:user.id,status:"LIVE"},include:{host:true}});const row=existing??await prisma.videoLiveSession.create({data:{publicId:`LIVE-${crypto.randomUUID().replaceAll("-","").slice(0,12).toUpperCase()}`,hostId:user.id,title,coverUrl:String(body?.coverUrl??"").trim()||null},include:{host:true}});emitToUser(user.publicId,"live-video:started",{success:true,data:{liveId:row.publicId}});return mobileJson({success:true,data:{session:await serializeVideoLive(row,requestOrigin(request))}},existing?200:201)}catch(e){return mobileApiError(e,"LIVE_START_FAILED")}}
