import { resolveUserPerks } from "./user-perks.js";
export async function serializeVideoLive(session,origin){const perks=(await resolveUserPerks([session.host],origin,["FRAMES","BADGES"])).get(session.host.publicId);return{id:session.publicId,title:session.title,coverUrl:session.coverUrl??null,status:session.status,hostAway:session.hostAway,viewerCount:session.viewerCount,peakViewers:session.peakViewers,likeCount:session.likeCount,giftIncome:session.giftIncome.toString(),revision:session.revision,startedAt:session.startedAt.toISOString(),endedAt:session.endedAt?.toISOString()??null,host:{publicId:session.host.publicId,name:session.host.name,profileImage:session.host.profileImage??null,frameUrl:perks?.frameUrl??null,badgeUrl:perks?.badgeUrl??null}}}
